import {createChatOrchestrator} from './src/orchestration/chatOrchestrator.js';
import {PromptBuilder} from './src/infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from './src/types/ai.js';

async function reproduce() {
  const callOrder: string[] = [];
  const hooks = {
    beforeSession: async () => {
      callOrder.push('beforeSession');
      throw new Error('beforeSession failure');
    },
    onError: async () => {
      callOrder.push('onError');
    },
    afterSession: async () => {
      callOrder.push('afterSession');
    },
  };

  const mockProvider: AIProvider = {
    async *sendMessage() {
      yield {type: 'text', text: 'hi'};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured() { return {}; }
  };

  const promptBuilder = new PromptBuilder({identity: 'test'});
  const orchestrator = createChatOrchestrator(mockProvider, promptBuilder, undefined, {hooks});

  try {
    await orchestrator.processMessage({
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content: 'hello', timestamp: new Date().toISOString()}]
    });
  } catch (e) {
    console.log('Caught expected error:', e.message);
  }

  console.log('Call order:', callOrder);
}

reproduce().catch(console.error);

