const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

describe('beforeSession throw reproduction', () => {
  it('demonstrates that onError and afterSession are NOT called when beforeSession throws', async () => {
    const callOrder: string[] = [];
    const hooks = {
      beforeSession: async () => {
        callOrder.push('beforeSession');
        throw new Error('beforeSession failure');
      },
      onError: async () => {
        callOrder.push('onError');
      },
      afterSession: async () => {
        callOrder.push('afterSession');
      },
    };

    const mockProvider: AIProvider = {
      async *sendMessage() {
        yield {type: 'text', text: 'hi'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured() { return {}; }
    };

    const promptBuilder = new PromptBuilder({identity: 'test'});
    const orchestrator = createChatOrchestrator(mockProvider, promptBuilder, undefined, {hooks});

    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('beforeSession failure');

    // Current behavior: only 'beforeSession' is called
    expect(callOrder).toEqual(['beforeSession']);
  });
});

